predicate_sources.AuditedMemoryStore:
def supports_capture_bundles(self) -> bool:
    """Whether the wrapped store can commit an atomic capture bundle."""
    return bool(capture_bundles_supported(self._store))

predicate_sources.BackendMemoryStoreAdapter:
def supports_capture_bundles(self) -> bool:
    """Whether the backend has a callable ``apply_capture_bundle``.

    The check ``apply_capture_bundle`` makes, without a write.
    """
    return callable(getattr(self._backend, "apply_capture_bundle", None))

predicate_sources.capture_bundles_supported:
def capture_bundles_supported(owner: object) -> bool:
    """Whether ``owner`` can commit an atomic capture bundle, without a write.

    An owner that forwards the capability answers ``supports_capture_bundles()``.
    Any other owner keeps the existing check: a callable ``apply_capture_bundle``.
    """
    supports = getattr(owner, "supports_capture_bundles", None)
    if callable(supports):
        return bool(supports())
    return callable(getattr(owner, "apply_capture_bundle", None))
